-- Supabase SQL script pro naplnění tabulky location_timeline (Časová osa z Google Maps)
CREATE TABLE IF NOT EXISTS public.location_timeline (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    place_name text NOT NULL,
    address text DEFAULT '',
    city text DEFAULT '',
    country text DEFAULT 'Česká republika',
    latitude numeric DEFAULT NULL,
    longitude numeric DEFAULT NULL,
    visit_date text NOT NULL,
    arrival_time text DEFAULT '',
    departure_time text DEFAULT '',
    activity text DEFAULT 'Návštěva',
    notes text DEFAULT '',
    created_at timestamp with time zone DEFAULT now()
);

ALTER TABLE public.location_timeline ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow anon all for location_timeline" ON public.location_timeline
    FOR ALL TO anon USING (true) WITH CHECK (true);






